package com.cinebook.catalog;
import com.cinebook.booking.*; import com.cinebook.common.ApiException; import jakarta.validation.constraints.Max; import jakarta.validation.constraints.Min; import org.springframework.cache.annotation.Cacheable; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.List;
@RestController @Validated @RequestMapping("/api")
public class CatalogController {
 private final MovieRepository movies;private final ShowtimeRepository shows;private final TheatreRepository theatres;private final ShowSeatRepository showSeats;
 public CatalogController(MovieRepository m,ShowtimeRepository s,TheatreRepository t,ShowSeatRepository ss){movies=m;shows=s;theatres=t;showSeats=ss;}
 @GetMapping("/movies") public Page<CatalogDtos.MovieView> movies(@RequestParam(required=false) String q,@RequestParam(required=false) String language,@RequestParam(required=false) String genre,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="12") @Min(1) @Max(48) int size,@RequestParam(defaultValue="rating") String sort){Sort ordering=switch(sort){case "title"->Sort.by("title").ascending();case "releaseDate"->Sort.by("releaseDate").descending();default->Sort.by("rating").descending();};Page<Movie> p=movies.search(blank(q),blank(language),blank(genre),PageRequest.of(page,size,ordering));return p.map(CatalogDtos::movie);}
 @Cacheable(value="movies",key="#id") @GetMapping("/movies/{id}") public CatalogDtos.MovieView movie(@PathVariable Long id){return movies.findByIdAndActiveTrue(id).map(CatalogDtos::movie).orElseThrow(()->new ApiException(404,"MOVIE_NOT_FOUND","Movie was not found"));}
 @GetMapping("/shows") public List<CatalogDtos.ShowtimeView> shows(@RequestParam(required=false) Long movieId,@RequestParam(required=false) String city){return shows.browse(Instant.now(),movieId,blank(city)).stream().map(CatalogDtos::show).toList();}
 @GetMapping("/shows/{id}") public CatalogDtos.ShowtimeView show(@PathVariable Long id){return shows.getFull(id).map(CatalogDtos::show).orElseThrow(()->new ApiException(404,"SHOW_NOT_FOUND","Showtime was not found"));}
 @GetMapping("/shows/{id}/seats") public List<CatalogDtos.SeatView> seats(@PathVariable Long id){if(!shows.existsById(id))throw new ApiException(404,"SHOW_NOT_FOUND","Showtime was not found");Instant now=Instant.now();return showSeats.mapForShow(id).stream().map(ss->{String status=ss.getStatus().name();if(ss.isEffectivelyAvailable(now))status="AVAILABLE";return new CatalogDtos.SeatView(ss.getSeat().getId(),ss.getSeat().getLabel(),ss.getSeat().getRowLabel(),ss.getSeat().getSeatNumber(),ss.getSeat().getType().name(),ss.getSeat().isAccessible(),status,ss.getPrice(),ss.getHoldExpiresAt());}).toList();}
 @GetMapping("/theatres") public List<CatalogDtos.TheatreView> theatres(){return theatres.findAllByActiveTrueOrderByCityAscNameAsc().stream().map(t->new CatalogDtos.TheatreView(t.getId(),t.getName(),t.getCity(),t.getAddress())).toList();}
 private static String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
